sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) { stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance'); return; }

  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var written = sam.recordPushOutcome('ATF-SAM-MON-0001', 'refused', 422, 'unresolved_subject');
  if (!written.ok) { stepResult.setFailed('recordPushOutcome should succeed: ' + JSON.stringify(written)); return; }

  var gr = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_integration', 'x_fed_day2_ops_integration'));
  if (!gr.get(written.sys_id)) { stepResult.setFailed('the row recordPushOutcome reported writing does not exist'); return; }
  if (gr.getValue('record_type') !== 'sam_push_outcome') { stepResult.setFailed('wrong record_type: ' + gr.getValue('record_type')); return; }
  if (gr.getValue('synthetic') !== 'true') { stepResult.setFailed('a row written under test_mode must be stamped synthetic=true'); return; }
  if (gr.getValue('state') !== 'refused') { stepResult.setFailed('wrong state: ' + gr.getValue('state')); return; }

  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();

  var before = sam.dailyOutcomeCounts(1);
  var beforeCheck = sam.sustainedFailureCheck(15, 1);

  sam.recordPushOutcome('ATF-SAM-MON-0002', 'refused', 422, 'unresolved_subject');
  sam.recordPushOutcome('ATF-SAM-MON-0003', 'refused', 400, 'bad_request');
  sam.recordPushOutcome('ATF-SAM-MON-0004', 'accepted', 201, 'created');

  var after = sam.dailyOutcomeCounts(1);
  var afterCheck = sam.sustainedFailureCheck(15, 1);

  if (after.refused !== before.refused || after.accepted !== before.accepted) {
    stepResult.setFailed('synthetic rows leaked into dailyOutcomeCounts: before=' + JSON.stringify(before) + ' after=' + JSON.stringify(after));
    return;
  }
  if (afterCheck.refused !== beforeCheck.refused) {
    stepResult.setFailed('synthetic rows leaked into sustainedFailureCheck: before=' + beforeCheck.refused + ' after=' + afterCheck.refused);
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var before = sam.dailyOutcomeCounts(1);

  var gr = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_integration', 'x_fed_day2_ops_integration'));
  gr.initialize();
  gr.setValue('record_type', 'sam_push_outcome');
  // sam_request_ref, not sam_request_id: telemetry rows must leave that column
  // free for sam_lineage (KIT-BUILD-SPEC.md 2b + its unique index).
  gr.setValue('sam_request_ref', 'ATF-SAM-MON-0005');
  gr.setValue('sam_flavor', gs.getProperty('x_fed_day2_ops.sam_flavor', 'identityiq'));
  gr.setValue('boundary', gs.getProperty('x_fed_day2_ops.boundary', 'gcc-moderate'));
  gr.setValue('state', 'refused');
  // reason_code / http_status are the columns monitoring reads now;
  // business_need is prose and is no longer parsed by anything.
  gr.setValue('reason_code', 'atf_monitoring_fixture');
  gr.setValue('http_status', 409);
  gr.setValue('business_need', 'http_status=409 reason=atf_monitoring_fixture');
  gr.setValue('test_mode', 'false');
  gr.setValue('synthetic', 'false');
  var id = gr.insert();
  if (!id) { stepResult.setFailed('fixture row insert failed'); return; }

  var after = sam.dailyOutcomeCounts(1);
  if (after.refused !== before.refused + 1) {
    stepResult.setFailed('expected refused count to increase by exactly 1, before=' + before.refused + ' after=' + after.refused);
    return;
  }
  var beforeReason = before.refusedByReason.atf_monitoring_fixture || 0;
  var afterReason = after.refusedByReason.atf_monitoring_fixture || 0;
  if (afterReason !== beforeReason + 1) {
    stepResult.setFailed('expected refusedByReason.atf_monitoring_fixture to increase by exactly 1, before=' + beforeReason + ' after=' + afterReason);
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var samRequestId = 'ATF-SAM-MON-0006';

  var lineage = sam.recordLineage(null, samRequestId, 'atf-correlation-mon-0006', {
    verified_by: 'pull-verify', verified_at: new GlideDateTime().getValue(),
    verified_authority: 'app-owner', verified_status: 'approved', verified_item: 'ATF-Test-Role'
  });
  if (!lineage.ok) { stepResult.setFailed('fixture lineage write failed: ' + JSON.stringify(lineage)); return; }
  var boundRitm = sam.attachRitmToLineage(lineage.sys_id, 'RITM0099999', 'fixture-ritm-sys-id');
  if (!boundRitm.ok) { stepResult.setFailed('fixture RITM binding failed: ' + JSON.stringify(boundRitm)); return; }

  var ev = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_evidence', 'x_fed_day2_ops_evidence'));
  ev.initialize();
  ev.setValue('verb', 'Add');
  ev.setValue('control', 'AC-2');
  ev.setValue('sam_request_id', samRequestId);
  ev.setValue('ritm', 'RITM0099999');
  ev.setValue('closed', 'true');
  ev.setValue('hash', 'atf-fixture-hash-0006');
  if (!ev.insert()) { stepResult.setFailed('fixture evidence write failed'); return; }

  var report = sam.correlationReport(samRequestId);
  if (!report.ok) { stepResult.setFailed('correlationReport should succeed: ' + JSON.stringify(report)); return; }
  if (!report.lineage || report.lineage.ritm !== 'RITM0099999') {
    stepResult.setFailed('correlationReport.lineage should show the bound RITM: ' + JSON.stringify(report.lineage));
    return;
  }
  if (!report.evidence.length || report.evidence[0].control !== 'AC-2') {
    stepResult.setFailed('correlationReport.evidence should include the fixture evidence row: ' + JSON.stringify(report.evidence));
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  var gr = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_integration', 'x_fed_day2_ops_integration'));
  gr.initialize();
  gr.setValue('record_type', 'sam_push_outcome');
  gr.setValue('sam_request_ref', 'ATF-SAM-MON-0006');
  gr.setValue('state', 'refused');
  gr.setValue('reason_code', 'atf fixture with spaces');
  gr.setValue('http_status', 422);
  gr.setValue('test_mode', 'false');
  gr.setValue('synthetic', 'false');
  if (!gr.insert()) { stepResult.setFailed('whitespace-code fixture insert failed'); return; }

  var counts = sam.dailyOutcomeCounts(1);
  if (!counts.refusedByReason['atf fixture with spaces']) {
    stepResult.setFailed('a reason code containing spaces must bucket under its full value; got buckets: ' +
                         JSON.stringify(counts.refusedByReason));
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
